def is_magical(n):
    digits = str(n)
    products = set()
    for length in range(1, len(digits) + 1):
        for combo in combinations(digits, length):
            product = 1
            for digit in combo:
                product *= int(digit)
            products.add(product)
    return sum(products) % 2 == 0

def magical_numbers():
    num = 0
    count = 0
    while True:
        if is_magical(num):
            count += 1
            yield num
        num += 1

def main():
    T = int(input().strip())
    magical_gen = magical_numbers()
    results = []
    for _ in range(T):
        K = int(input().strip())
        result = None
        for _ in range(K):
            result = next(magical_gen)
        results.append(result)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
